from review import card,save,DATE
i='TCS-3557';_,c=card(i);refs=c['references'];refs[0]['locator']='Sections 2.1–2.3, finite instances, queries and safe constant-free rules; Section 7, stratified semantics; Section 9, Str-Datalog(≠) ∩ E = Sp-Datalog(≠).'
refs += [dict(id='networking',title='Weaker Forms of Monotonicity for Declarative Networking: A More Fine-Grained Answer to the CALM-Conjecture',authors='Tom Ameloot; Bas Ketsman; Frank Neven; Daniel Zinn',year=2016,url='https://doi.org/10.1145/2809784',locator='TODS 40(4), article 21; domain-distinct monotonicity. The authors’ PODS 2014 poster explicitly defines the domain condition and induced instances.'),dict(id='poster',title='Weaker Forms of Monotonicity for Declarative Networking',authors='Tom Ameloot; Bas Ketsman; Frank Neven; Daniel Zinn',year=2014,url='https://www.basketsman.com/public/documents/posters/poster_pods2014.pdf',locator='Authors’ PODS poster: domain-distinct facts and restriction to an induced instance.'),dict(id='later',title='Extension Preservation in the Finite and Prefix Classes of First Order Logic',authors='Anuj Dawar; Abhisekh Sankaran',year=2021,url='https://doi.org/10.4230/LIPIcs.CSL.2021.18',locator='Section 2, Datalog(¬) allows negation only on extensional predicates and equality; Theorem 4.1 concerns first-order quantifier prefixes, not stratified-to-semi-positive equivalence.')]
save(i,dict(title='Does extension preservation eliminate stratified intensional negation?',formal='For every finite input schema and every generic query q expressible by a safe, constant-free stratified Datalog program with disequality, suppose that q is preserved under induced extensions of finite database instances. Must q be expressible by a safe, constant-free semi-positive Datalog program with disequality over the same input schema and with the same output arity? In the source’s notation, is Str-Datalog(≠) ∩ E = Sp-Datalog(≠)? Preservation under induced extensions is defined below. The inclusion from right to left is known; the question is the converse.',definitions='Fix an infinite set D of data values. An input schema is a finite set of relation names with specified finite arities. A database instance I is a finite set of facts R(a₁,…,aᵣ), with aᵢ∈D. Its active domain adom(I) is the set of values occurring in those facts. J is an induced extension of I when adom(I)⊆adom(J) and, for every input relation R of arity r, Rᴵ=Rᴶ∩adom(I)ʳ. Thus all relations on old tuples are unchanged; every new fact of positive arity contains at least one new value. Nullary facts must remain unchanged. A query q of arity k maps I to a finite set of k-tuples, and is generic if permuting D commutes with q. For k=0, the empty tuple represents true. Membership in E means q(I)⊆q(J) for every such pair I,J. A program has finitely many rules H(ȳ)←A₁,…,Aᵤ,¬B₁,…,¬Bᵥ,z₁≠w₁,…,zₛ≠wₛ. Atoms use relation names and variables, with no constants, function symbols or value invention. Every variable in the head, a negative atom or a disequality must also occur in a positive body atom. Input relations are extensional and never defined by a rule; derived relations are intensional. A stratification assigns levels to intensional relations so that positive dependencies have no higher level than the head and negative dependencies have strictly lower level. Evaluate levels in order, starting new derived relations empty and repeatedly adding every head whose instantiated body holds until no further fact is added; lower levels and input facts stay fixed. The distinguished output relation defines q. A semi-positive program permits negative atoms only on input relations. Equality can be represented by repeated variables, and disequality is actual inequality of data values. Programs may introduce finitely many auxiliary intensional relations of arbitrary finite arity. The requested equivalence is equality of outputs on every finite input instance, with no built-in order or additional input relations.',question_type='yes_no',answer_criterion='Prove that every query satisfying the stated stratified definability and extension-preservation conditions has a semi-positive definition, or exhibit a stratified extension-preserved query and prove that no semi-positive program with disequality defines it. Failure of one proposed rewrite is insufficient. The claim concerns existence of equivalent definitions; it imposes neither an effective recognition algorithm for E nor a bound on rewrite size.',context_blocks=[dict(title='Which changes to the input are allowed matters',text='Ordinary monotonicity permits adding arbitrary facts, including facts involving only existing values. Induced-extension preservation permits new values and facts involving them while keeping every old tuple’s membership fixed. Confusing these two conditions changes the source question.',citation='poster'),dict(title='The target still permits input negation',text='The desired program may test absence of an input fact. What it must eliminate is negation of derived relations across strata. This is therefore different from asking for a completely positive Datalog definition.',citation='primary'),dict(title='The source settles neighbouring comparisons',text='Ketsman and Koch separate several monotone and positive Datalog fragments, but explicitly leave this extension-preservation equality open. The known semi-positive inclusion does not supply the reverse inclusion.',citation='primary'),dict(title='Related finite-model results address another comparison',text='Dawar and Sankaran’s 2021 paper builds extension-preserved properties with strong first-order quantifier-prefix requirements. Its notation Datalog(¬) permits only extensional negation and disequality. Those results do not establish a separation between the stratified and semi-positive classes asked about here.',citation='later')],why='Would characterize when a semantic guarantee about growing databases suffices to remove negation between recursive stages, clarifying the expressive resources needed for distributed queries.',references=refs,progress=[dict(date='2016',text='Work on weaker monotonicity connects domain-distinct input growth to coordination in declarative networking.',citation='networking'),dict(date='2020',text='The source records the semi-positive inclusion and leaves its converse within stratified Datalog open.',citation='primary'),dict(date='2021',text='Extension-preservation results for first-order prefix classes use semi-positive Datalog, a different expressiveness comparison.',citation='later')],status='open',status_note='Recovered the exact equality from the 2020 conclusion and checked the finite-instance, safety, disequality and stratification conventions. Checked subsequent extension-preservation literature and searched for this equality and domain-distinct monotonicity; no matching resolution was located as of 12 September 2026. This search is not exhaustive and is not an independent mathematical proof of openness.',model_self_contained=True,requires_context=False,importance=dict(score=c['importance']['score'],method='editorial',reason='A semantic-to-syntactic characterization question about recursive negation, with relevance to coordination in distributed database evaluation. Existing score retained.',assessed_on=DATE),review_note='Restored the truncated class equality and ≠ symbol, defined induced extensions and both program classes, and separated neighbouring preservation results.',working_summary=dict(sentences=['Stratified Datalog can negate relations already computed in earlier stages.','Semi-positive Datalog only negates input relations.','The question asks whether preserving answers when new values extend a database always permits the simpler semi-positive form.','The input growth must preserve every relation on tuples of old values, which differs from unrestricted monotonicity.','The source leaves this converse expressiveness question open, and the checked later first-order preservation results do not resolve it.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','poster','later'])),notes=['Recovered Str-Datalog(≠) ∩ E = Sp-Datalog(≠).','Defined finite active-domain induced extensions, generic queries, safe rules and stratum semantics.','Separated input negation from intensional negation and existence of rewriting from a rewriting algorithm.','Checked related 2021 preservation result and searched later literature.'],checked_sources=[r['url'] for r in refs])
